        2 => 'twenty', 3 => 'thirty', 4 => 'forty', 5 => 'fifty', 6 => 'sixty', 7 => 'seventy', 8 => 'eighty', 9 => 'ninety'
    );
    $hundreds = array(
        1 => 'one hundred', 2 => 'two hundred', 3 => 'three hundred', 4 => 'four hundred', 5 => 'five hundred', 6 => 'six hundred', 7 => 'seven hundred', 8 => 'eight hundred', 9 => 'nine hundred'
    );
    $words = array();
    if ($number < 0) {
        $words[] = 'minus';
        $number = abs($number);
    }
    if (($number / 1000) >= 1) {
        $thousands = floor($number / 1000);
        if ($thousands >= 100) {
            $words[] = $hundreds[floor($thousands / 100)];
            $thousands = $thousands % 100;
        }
        if ($thousands >= 20) {
            $words[] = $tens[floor($thousands / 10)];
            $thousands = $thousands % 10;
        }
        if ($thousands >= 1) {
            $words[] = $ones[$thousands];
        }
        $words[] = 'thousand';
        $number = $number % 1000;
    }
