import java.util.Scanner;
public class CommuteCostSavings {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        // Get input from user
        System.out.print("Enter the total distance traveled in miles: ");
        double distance = scanner.nextDouble();
        System.out.print("Enter the price of gas per gallon: ");
        double gasPrice = scanner.nextDouble();
        System.out.print("Enter the fuel efficiency of your vehicle in miles per gallon: ");
        double fuelEfficiency = scanner.nextDouble();
        System.out.print("Enter the number of commuters (including yourself): ");
        int numCommuters = scanner.nextInt();
        // Calculate cost of driving alone
        double costDrivingAlone = (distance / fuelEfficiency) * gasPrice;
        // Calculate cost of carpooling
        double costCarpooling = (distance / fuelEfficiency) * gasPrice / numCommuters;
        // Calculate cost savings
        double costSavings = costDrivingAlone - costCarpooling;
        // Print results
        System.out.println("Cost of driving alone: $" + costDrivingAlone);
        System.out.println("Cost of carpooling: $" + costCarpooling);
        System.out.println("Cost savings: $" + costSavings);
    }
}
