```cpp
#include <iostream>
#include <string>
using namespace std;
struct Language {
    string name;
    int year;
};
void swap(Language& a, Language& b) {
    Language temp = a;
    a = b;
    b = temp;
}
void bubbleSort(Language arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j].year > arr[j + 1].year) {
                swap(arr[j], arr[j + 1]);
            }
        }
    }
}
int main() {
    Language languages[3] = {
        {"Hebrew", -1200},
        {"Sanskrit", -1500},
        {"Greek", -800}
    };
    bubbleSort(languages, 3);
    cout << "Languages sorted by earliest documented appearance:\n";
    for (int i = 0; i < 3; i++) {
        cout << languages[i].name << " (" << languages[i].year << " BCE)\n";
    }
    cout << "\nBrief explanation for each language's impact:\n";
    cout << "Hebrew: The Hebrew language has had a significant impact on Western culture and religion, as it is the language of the Jewish scriptures.\n";
    cout << "Sanskrit: Sanskrit is considered the mother of all Indo-European languages and has had a profound influence on Indian culture, religion, and literature.\n";
