public static bool IsInstanceOfTypeOrDerived(Type baseType, object obj)
{
    if (obj == null)
        return false;
    Type objectType = obj.GetType();
    if (objectType == baseType || objectType.IsSubclassOf(baseType))
    {
        return true;
    }
    // Check if the object implements an interface that derives from the base type
    Type[] interfaces = objectType.GetInterfaces();
    foreach (Type i in interfaces)
    {
        if (i.IsGenericType && i.GetGenericTypeDefinition() == baseType)
        {
            return true;
        }
    }
    // Check if the object has a base class that derives from the base type
    Type baseClass = objectType.BaseType;
    while (baseClass != null)
    {
        if (baseClass == baseType)
        {
            return true;
        }
        baseClass = baseClass.BaseType;
    }
    return false;
}
```
