Sure! Here is a sample code that uses the Yelp API and C++ programming language to search for the top five Italian restaurants in Manhattan with the highest rating, filtered by price range:
```c++
#include <iostream>
#include <string>
#include <curl/curl.h>
#include <jsoncpp/json/json.h>
using namespace std;
// Yelp API credentials
const string API_KEY = "YOUR_API_KEY_HERE";
// Yelp API endpoint and parameters
const string API_ENDPOINT = "https://api.yelp.com/v3/businesses/search";
const string API_PARAMS = "?term=italian&location=Manhattan&categories=restaurants&sort_by=rating&price=2,3&limit=5";
// Callback function for CURL
size_t write_callback(char* ptr, size_t size, size_t nmemb, void* userdata) {
    ((string*)userdata)->append(ptr, size * nmemb);
    return size * nmemb;
}
int main() {
    // Initialize CURL
    CURL* curl = curl_easy_init();
    if (curl) {
        // Set CURL options
        curl_easy_setopt(curl, CURLOPT_URL, (API_ENDPOINT + API_PARAMS).c_str());
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, {"Authorization: Bearer " + API_KEY});
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        // Send CURL request and receive response
        string response;
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
        CURLcode res = curl_easy_perform(curl);
        // Check for CURL errors
        if (res != CURLE_OK) {
            cerr << "CURL error: " << curl_easy_strerror(res) << endl;
            return 1;
        }
        // Parse JSON response using JsonCpp
        Json::Value root;
        Json::Reader reader;
        bool success = reader.parse(response, root);
        if (!success) {
            cerr << "JSON parsing error: " << reader.getFormattedErrorMessages() << endl;
            return 1;
        }
        // Extract restaurant information from JSON response
        for (int i = 0; i < root["businesses"].size(); i++) {
            string name = root["businesses"][i]["name"].asString();
            string address = root["businesses"][i]["location"]["address1"].asString();
            string phone = root["businesses"][i]["phone"].asString();
            double rating = root["businesses"][i]["rating"].asDouble();
            cout << "Name: " << name << endl;
            cout << "Address: " << address << endl;
            cout << "Phone: " << phone << endl;
            cout << "Rating: " << rating << endl;
            cout << endl;
        }
        // Cleanup CURL
        curl_easy_cleanup(curl);
    } else {
        cerr << "CURL initialization error" << endl;
        return 1;
    }
    return 0;
}
```
Note that you need to replace `YOUR_API_KEY_HERE` with your actual Yelp API key. Also, make sure to install the required dependencies (CURL and JsonCpp) and link them properly when compiling the code.

