    if err != nil {
        log.Fatal(err)
    }
    var diversifiedPortfolio []Stock
    for _, stock := range portfolio.Stocks {
        if parseMarketCapitalization(stock.MarketCapitalization) >= 10000000000 {
            if stock.Industry == "Technology" && stock.Risk == "High" && stock.Location == "Global" {
                diversifiedPortfolio = append(diversifiedPortfolio, stock)
            }
        }
    }
    fmt.Println(diversifiedPortfolio)
}
func parseMarketCapitalization(marketCap string) float64 {
    marketCap = strings.ReplaceAll(marketCap, "T", "000000000000")
    marketCap = strings.ReplaceAll(marketCap, "B", "000000000")
    marketCap = strings.ReplaceAll(marketCap, "M", "000000")
    marketCap = strings.ReplaceAll(marketCap, ",", "")
    marketCapFloat, _ := strconv.ParseFloat(marketCap, 64)
    return marketCapFloat
}
