```swift
import Foundation
// Generate a random distance between 5000 and 10000 meters
let distance = Int.random(in: 5000...10000)
// Define the speed and break intervals for the cheetah and the zebra
let cheetahSpeed = 60 // meters per second
let cheetahBreakInterval = 500 // meters
let cheetahBreakDuration = 15 // seconds
let zebraSpeed = 40 // meters per second
let zebraBreakInterval = 1000 // meters
let zebraBreakDuration = 45 // seconds
// Define variables to keep track of the positions and times of the cheetah and the zebra
var cheetahPosition = 0
var zebraPosition = 0
var cheetahTime = 0.0
var zebraTime = 0.0
// Simulate the race until one of the animals reaches the finish line
while cheetahPosition < distance && zebraPosition < distance {
    // Move the cheetah
    cheetahPosition += cheetahSpeed
    cheetahTime += 1.0 / Double(cheetahSpeed)
    if cheetahPosition % cheetahBreakInterval == 0 {
        cheetahPosition -= min(cheetahPosition, cheetahBreakDuration * cheetahSpeed)
        cheetahTime += Double(cheetahBreakDuration)
    }
    // Move the zebra
    zebraPosition += zebraSpeed
    zebraTime += 1.0 / Double(zebraSpeed)
    if zebraPosition % zebraBreakInterval == 0 {
        zebraPosition -= min(zebraPosition, zebraBreakDuration * zebraSpeed)
        zebraTime += Double(zebraBreakDuration)
    }
}
// Determine the winner and the time it took for them to reach the finish line
if cheetahPosition >= distance {
    print("The cheetah won the race in \(cheetahTime) seconds!")
} else {
    print("The zebra won the race in \(zebraTime) seconds!")
