```
#include <iostream>
#include <cmath>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;
int convertToDecimal(int base, string value) {
    int decimalValue = 0;
    int power = 0;
    for (int i = value.size() - 1; i >= 0; i--) {
        int digit = find(digits.begin(), digits.end(), value[i]) - digits.begin();
        decimalValue += digit * pow(base, power);
        power++;
    }
    return decimalValue;
}
int main() {
    vector<string> digits = {"0", "1", "2", "3", "4", "5", "6"};
    // Parse the JSON object
    int numeratorBase = 7;
    string numeratorValue = "3";
    int denominatorBase = 7;
    string denominatorValue = "2";
    // Convert the numerator and denominator to base 10
    int numeratorDecimal = convertToDecimal(numeratorBase, numeratorValue);
    int denominatorDecimal = convertToDecimal(denominatorBase, denominatorValue);
    // Calculate the decimal value of the fraction
    double decimalValue = (double)numeratorDecimal / denominatorDecimal;
    cout << decimalValue << endl;
    return 0;
}
```
This code defines a function `convertToDecimal` that takes a base and a value in the form of a string, and converts it to base 10. We then use this function to convert the numerator and denominator to base 10, and then calculate the decimal value of the fraction by dividing the numerator by the denominator.

