Here is a possible implementation of the `areAnagrams` function in Go:
```go
import (
    "sort"
    "strings"
)
func areAnagrams(s1, s2 string) bool {
    s1 = strings.ToLower(s1)
    s2 = strings.ToLower(s2)
    s1 = removeSpecialChars(s1)
    s2 = removeSpecialChars(s2)
    if len(s1) != len(s2) {
        return false
    }
    s1Chars := strings.Split(s1, "")
    s2Chars := strings.Split(s2, "")
    sort.Strings(s1Chars)
    sort.Strings(s2Chars)
    for i := range s1Chars {
        if s1Chars[i] != s2Chars[i] {
            return false
        }
    }
    return true
}
func removeSpecialChars(s string) string {
    var result strings.Builder
    for _, c := range s {
        if c >= 'a' && c <= 'z' {
            result.WriteRune(c)
        }
    }
    return result.String()
}
```
This implementation converts both strings to lowercase and removes all special characters (i.e., any character that is not a lowercase letter). It then checks if the two strings have the same length and sorts their characters to compare them.
